INSERT IGNORE INTO `player_levelstats` (`race`,`class`,`level`,`str`,`agi`,`sta`,`inte`) SELECT 18, 11, `level`, `str`, `agi`, `sta`, `inte` FROM `player_levelstats` WHERE `race` = 4 AND `class` = 11;
